test('Collection network sync is idempotent, preserves hidden references and reports capacity exclusions',async t=>{
 const dir=fixture(t);C.merge(dir,[1,2,3].map(n=>({id:'mal:anime:'+n,provider:'myanimelist',providerId:String(n),title:'Item '+n,domain:'anime',kind:'anime',rating:n===1?9:null})));
 const setup=()=>require('../src/recall-service').registerRecall({ipcMain:{handle(){}},authorized:()=>true,userData:()=>dir,catalogStore:()=>({list:()=>[],get:()=>null})});let s=setup();s.store.remove('collection:mal:anime:1');const response=await s.handle({}, {action:'collection-sync'}),report=response.sync;assert.equal(response.ok,true);assert.equal(report.hidden,1);assert.equal(report.added,0);assert.equal(s.store.snapshot().refs.length,3);assert.equal(s.store.snapshot().refs.find(r=>r.id==='collection:mal:anime:1').hidden,true);
 const file=path.join(dir,'recall-network.json'),d=s.store.snapshot();for(let n=d.refs.length;n<2000;n++)d.refs.push({id:'fixture:'+n,ref:{kind:'fixture',id:String(n)}});fs.writeFileSync(file,JSON.stringify(d));C.merge(dir,[{id:'mal:manga:4',title:'Extra',domain:'manga',kind:'manhwa',rating:null}]);s=setup();assert.equal(s.syncCollection().capacityExcluded,1);assert.equal(s.syncCollection().hidden,1);
});
