 assert.notEqual(C.parseMal(xml('manga'))[0].id,row.id);assert.throws(()=>C.parseMal(xml('anime','11')));assert.throws(()=>C.parseMal('<!DOCTYPE myanimelist SYSTEM "file:///secret"><myanimelist/>'));assert.throws(()=>C.parseMal('<myanimelist><anime>'));
