test('Pause reasons are separate from ratings, imported comments, status and progress, with revision-safe edits and explicit empty removal',t=>{
 const dir=fixture(t),G=require('../src/personal-library-groups');C.merge(dir,[{id:'a',title:'Anime',domain:'anime',kind:'anime',status:'paused',rating:9,progress:7,note:'Imported comment'}]);const rows=()=>C.read(dir).rows.map(r=>({...r,origin:'collection'})),g=G.create({root:dir,rows,catalog:()=>null,now:()=>1000}),reference={id:'a',origin:'collection'},before=fs.readFileSync(path.join(dir,'personal-collection.json'),'utf8'),initial=g.noteGet(reference),saved=g.noteSave({ref:reference,revision:initial.revision,context:'paused',text:'Need more time'});assert.equal(saved.note.text,'Need more time');assert.equal(saved.note.updatedAt,1000);assert.equal(fs.readFileSync(path.join(dir,'personal-collection.json'),'utf8'),before);assert.throws(()=>g.noteSave({ref:reference,revision:initial.revision,context:'dropped',text:'Old'}),/changed/);let row=C.read(dir).rows[0];C.save(dir,{id:row.id,revision:C.hash(row),patch:{status:'watching'}});assert.equal(g.noteGet(reference).note.context,'paused');assert.equal(C.read(dir).rows[0].rating,9);g.noteSave({ref:reference,revision:saved.revision,context:'paused',text:''});assert.equal(g.noteGet(reference).note,null);assert.equal(C.read(dir).rows[0].note,'Imported comment');
});

test('Bulk/collection/note IPC binds previews to owner and keeps pause notes out of profile and imported comments',async t=>{
 const dir=fixture(t);C.merge(dir,[{id:'a',title:'Anime',domain:'anime',kind:'anime',status:'watching',rating:3,progress:2,note:'Imported comment'}]);let handle;require('../src/media-shelf-service').registerMediaShelf({ipcMain:{handle(_n,fn){handle=fn;}},authorized:e=>e.allowed,userData:()=>dir,catalogStore:()=>({list:()=>[]})});const api=(input,id=1)=>handle({allowed:true,sender:{id}},input),reference={id:'a',origin:'collection'},initial=await api({action:'collection-groups-list'}),group=await api({action:'collection-group-save',name:'My group',description:'Description',members:[reference],order:[reference],coverRef:null,revision:initial.revision});assert.equal(group.ok,true);const plan=await api({action:'collection-bulk-preview',refs:[reference],operation:'status',status:'paused'});assert.equal((await api({action:'collection-bulk-apply',token:plan.token},2)).ok,false);assert.equal(C.read(dir).rows[0].status,'watching');assert.equal((await api({action:'collection-bulk-apply',token:plan.token})).updated,1);const before=fs.readFileSync(path.join(dir,'personal-collection.json'),'utf8'),note=await api({action:'collection-pause-note',ref:reference});assert.equal((await api({action:'collection-pause-note-save',ref:reference,revision:note.revision,context:'paused',text:'Will return later'})).ok,true);assert.equal(fs.readFileSync(path.join(dir,'personal-collection.json'),'utf8'),before);assert.equal((await api({action:'collection-list'})).rows[0].hasPauseNote,true);const profile=profileFor({},[],C.read(dir).rows,'anime');assert.equal(profile.rated,1);assert.equal(profile.average,1.5);assert.equal(C.read(dir).rows[0].note,'Imported comment');const exported=await api({action:'collection-archive-export',format:'json'}),json=JSON.parse(exported.text);assert.equal(json.collections[0].name,'My group');assert.equal(json.pauseNotes[0].text,'Will return later');assert.equal(json.rows[0].pauseContext,'paused');const other=JSON.parse((await api({action:'collection-archive-export',format:'json',domain:'manga'})).text);assert.equal(other.pauseNotes.length,0);assert.equal(other.collections.length,0);const currentNote=await api({action:'collection-pause-note',ref:reference});await api({action:'collection-pause-note-save',ref:reference,revision:currentNote.revision,context:'paused',text:'=not a spreadsheet formula'});const csv=await api({action:'collection-archive-export',format:'csv'});assert(csv.text.includes("'=not a spreadsheet formula"));assert.equal((await handle({allowed:false},{action:'collection-bulk-preview'})).ok,false);assert.equal((await handle({allowed:false},{action:'collection-pause-note',ref:reference})).ok,false);
});

